try{$token=text_value($_GET['token']??'',64);$s=row('SELECT trip_id FROM rs_shares WHERE token_hash=? AND revoked_at IS NULL AND expires_at>UTC_TIMESTAMP()',[hash('sha256',$token)]);if(!$s)fail(404,'This trip link expired or was revoked.');$t=row('SELECT status,snapshot FROM rs_trips WHERE id=?',[$s['trip_id']]);$data=decode($t['snapshot']);header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'");$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');echo '<!doctype html><meta name="viewport" content="width=device-width"><title>RideShare trip</title><style>body{background:#101211;color:#f4f6f4;font:18px system-ui;max-width:520px;margin:48px auto;padding:24px}small{color:#afb8b2}</style><h1>Shared trip</h1><p>'.$esc($data['product']['name']).' · '.$esc(str_replace('_',' ',$t['status'])).'</p><p>'.$esc($data['pickup']['name']).' → '.$esc($data['destination']['name']).'</p><small>Refresh for the latest confirmed trip stage. This link does not dispatch emergency assistance.</small>';}
